def row(label: Any, value: Any) -> Any:
    v: Any = esc(value)
    return "" if (v == "") else ("<tr><th>" + esc(label) + "</th><td>" + js.s(v) + "</td></tr>")


def card(label: Any, value: Any) -> Any:
    v: Any = esc(value)
    return (
        ""
        if (v == "")
        else (
            '<div class="card"><div class="label">'
            + esc(label)
            + '</div><div class="value">'
            + js.s(v)
            + "</div></div>"
        )
    )


def renderHoroscopeHtml(data: Any, branding: Any = js.UNDEF) -> Any:
    data = withoutNullItems({**data, "language": safeLocale(js.get(data, "language"))})
    b: Any = resolveBranding(js.UNDEF, branding)
    t: Any = makeLabeler(LABELS, js.get(data, "language"))
    period: Any = (
        js.get(data, "period") if (js.type_of(js.get(data, "period")) == "string") else "daily"
    )
    title: Any = _v1 if js.truthy(_v1 := t(("title_" + js.s(period)))) else t("title_daily")
    subject: Any = esc(
        (_v2 if js.truthy(_v2 := js.get(data, "rashi_label")) else js.get(data, "rashi"))
    )
    cover: Any = (
        ('\n<section class="cover">\n  ')
        + js.s(coverBrandingHtml(b))
        + ("\n  <h1>")
        + esc(title)
        + ("</h1>\n  ")
        + (('<div class="subject">' + js.s(subject) + "</div>") if js.truthy(subject) else "")
        + ("\n  ")
        + (
            (
                '<div class="meta">'
                + esc(t("period"))
                + ": "
                + esc(js.get(data, "period_key"))
                + "</div>"
            )
            if js.truthy(js.get(data, "period_key"))
            else ""
        )
        + ("\n</section>")
    )
    headline: Any = (
        ("<p><strong>" + esc(js.get(data, "headline")) + "</strong></p>")
        if js.truthy(js.get(data, "headline"))
        else ""
    )
    transits: Any = ""
    if js.is_array(js.get(data, "slow_movers")) and js.truthy(
        js.length(js.get(data, "slow_movers"))
    ):

        def _fn3(sm: Any) -> Any:
            fallbackHead: Any = js.join(
                js.map_(
                    js.filter_([js.get(sm, "planet"), js.get(sm, "current_sign")], js.truthy),
                    (lambda x: esc(x)),
                ),
                " — ",
            )
            heading: Any = js.or_(esc(js.get(sm, "heading")), fallbackHead)
            cites: Any = (
                (
                    '<div class="citations">'
                    + esc(t("sources"))
                    + ": "
                    + escList(js.get(sm, "citations"))
                    + "</div>"
                )
                if (
                    js.is_array(js.get(sm, "citations"))
                    and js.truthy(js.length(js.get(sm, "citations")))
                )
                else ""
            )
            return (
                '<div class="narrative-section"><h3>'
                + js.s(heading)
                + '</h3><div class="body">'
                + esc(js.get(sm, "body"))
                + "</div>"
                + js.s(cites)
                + "</div>"
            )

        blocks: Any = js.join(js.map_(js.get(data, "slow_movers"), _fn3), "\n")
        transits = "<h2>" + esc(t("section_transits")) + "</h2>\n" + js.s(blocks)
    panchang: Any = ""
    p: Any = js.get(data, "panchang")
    if js.truthy(p):
        rows: Any = js.join(
            [
                row(
                    t("tithi"),
                    js.join(
                        js.filter_([js.get(p, "tithi"), js.get(p, "paksha")], js.truthy), " / "
                    ),
                ),
                row(t("nakshatra"), js.get(p, "nakshatra")),
                row(t("yoga"), js.get(p, "yoga")),
                row(t("karana"), js.get(p, "karana")),
                row(t("vaar"), js.get(p, "vaar")),
                row(t("rahu_kaal"), js.get(p, "rahu_kaal")),
                row(t("auspicious_window"), js.get(p, "auspicious_window")),
                row(t("sunrise"), js.get(p, "sunrise")),
                row(t("sunset"), js.get(p, "sunset")),
            ],
            "",
        )
        if js.truthy(rows):
            panchang = (
                "<h2>" + esc(t("section_panchang")) + "</h2><table>" + js.s(rows) + "</table>"
            )
    lucky: Any = ""
    l: Any = js.get(data, "lucky")
    if js.truthy(l):
        cards: Any = js.join(
            [
                card(t("lucky_color"), js.get(l, "color")),
                card(
                    t("lucky_number"),
                    (js.get(l, "number") if (js.type_of(js.get(l, "number")) == "number") else ""),
                ),
                card(t("lucky_direction"), js.get(l, "direction")),
                card(t("lucky_time"), js.get(l, "time")),
            ],
            "",
        )
        if js.truthy(cards):
            lucky = (
                "<h2>"
                + esc(t("section_lucky"))
                + '</h2><div class="cards">'
                + js.s(cards)
                + "</div>"
            )
    bodyHtml: Any = (
        js.s(cover)
        + "\n"
        + js.s(headline)
        + "\n"
        + js.s(transits)
        + "\n"
        + js.s(panchang)
        + "\n"
        + js.s(lucky)
    )
    return layoutDocument(
        {
            "lang": js.or_(js.get(data, "language"), "en"),
            "title": (
                js.s(title)
                + (
                    (
                        " — "
                        + js.s(
                            (
                                _v4
                                if js.truthy(_v4 := js.get(data, "rashi_label"))
                                else js.get(data, "rashi")
                            )
                        )
                    )
                    if js.truthy(subject)
                    else ""
                )
            ),
            "branding": b,
            "bodyHtml": bodyHtml,
        }
    )
